import React, { useEffect, useState } from 'react'
import { API_OPT } from '../Utils/constants'
import { useDispatch, useSelector } from 'react-redux';
import { addTrailer } from '../Utils/movieSlice';

const VideoBg = ({ movieId }) => {

    const dispatch=useDispatch();
    const trailerVideo=useSelector(store=>store.movies?.trailer)
    // const [trailerID,setTrailerID]=useState(null);
    const getMovieVideo = async () => {
        const data = await fetch('https://api.themoviedb.org/3/movie/1241982/videos?language=en-US', API_OPT);
        const json = await data.json();
        // console.log(json)
        const filterTrailer = json.results.filter((v) => v.type == "Trailer")
        const trailer = filterTrailer.length ? filterTrailer[0] : json.results[0];
        // setTrailerID(trailer.key) 1way
        dispatch(addTrailer(trailer));
        // console.log(trailer)
    }
    useEffect(() => {
        getMovieVideo()
    }, [])
    return (
        <div>
            <iframe width="560" height="315" src={"https://www.youtube.com/embed/"} title="YouTube video player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerPolicy="strict-origin-when-cross-origin" allowFullScreen></iframe>
        </div>
    )
}

export default VideoBg
